import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>{count}</p>
      <button type="button" onClick={() => setCount(c => c + 1)}>
        Increment
      </button>
    </div>
  )
}

import { useEffect, useState } from 'react'

export default function FetchUsers() {
  const [users, setUsers] = useState(null)
  const [error, setError] = useState(null)

  useEffect(() => {
    const controller = new AbortController()

    fetch('https://jsonplaceholder.typicode.com/users', { signal: controller.signal })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return res.json()
      })
      .then(setUsers)
      .catch(err => {
        if (err.name !== 'AbortError') setError(err)
      })

    return () => controller.abort()
  }, [])

  if (error) return <p>Error: {error.message}</p>
  if (!users) return <p>Loading…</p>

  return (
    <ul>
      {users.map(user => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  )
}

import { useState } from 'react'

const columns = ['name', 'price', 'qty']

export default function FilterTable({ rows }) {
  const [query, setQuery] = useState('')
  const [sort, setSort] = useState({ key: null, dir: 1 })

  const q = query.toLowerCase()
  const visible = rows.filter(row => row.name.toLowerCase().includes(q))

  if (sort.key) {
    visible.sort((a, b) => {
      const x = a[sort.key]
      const y = b[sort.key]
      const cmp = typeof x === 'string' ? x.localeCompare(y) : x - y
      return cmp * sort.dir
    })
  }

  const total = visible.reduce((sum, row) => sum + row.price * row.qty, 0)

  function toggleSort(key) {
    setSort(prev => (prev.key === key ? { key, dir: -prev.dir } : { key, dir: 1 }))
  }

  return (
    <div>
      <input
        type="search"
        value={query}
        onChange={e => setQuery(e.target.value)}
        placeholder="Search"
      />
      <table>
        <thead>
          <tr>
            {columns.map(col => (
              <th key={col} onClick={() => toggleSort(col)}>
                {col}
                {sort.key === col && (sort.dir === 1 ? ' ▲' : ' ▼')}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {visible.map((row, i) => (
            <tr key={`${row.name}-${i}`}>
              <td>{row.name}</td>
              <td>{row.price}</td>
              <td>{row.qty}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={2}>Total</td>
            <td>{total}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  )
}

export default function Hello({ name }) {
  return <p>Hello, {name}!</p>
}

import { useEffect, useState } from 'react'

async function request(url, options) {
  const res = await fetch(url, options)
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return res
}

export default function KvBrowser({ baseUrl }) {
  const [keys, setKeys] = useState([])
  const [version, setVersion] = useState(0)
  const [selected, setSelected] = useState(null)
  const [newKey, setNewKey] = useState('')
  const [newValue, setNewValue] = useState('')
  const [error, setError] = useState(null)

  const keyUrl = key => `${baseUrl}/kv/${encodeURIComponent(key)}`
  const reload = () => setVersion(v => v + 1)

  useEffect(() => {
    const controller = new AbortController()

    request(`${baseUrl}/kv`, { signal: controller.signal })
      .then(res => res.json())
      .then(setKeys)
      .catch(err => {
        if (err.name !== 'AbortError') setError(err.message)
      })

    return () => controller.abort()
  }, [baseUrl, version])

  async function show(key) {
    try {
      const res = await request(keyUrl(key))
      setSelected({ key, value: await res.text() })
      setError(null)
    } catch (err) {
      setError(err.message)
    }
  }

  async function handleSave(e) {
    e.preventDefault()
    if (!newKey) return
    try {
      await request(keyUrl(newKey), { method: 'PUT', body: newValue })
      setNewKey('')
      setNewValue('')
      setError(null)
    } catch (err) {
      setError(err.message)
    }
    reload()
  }

  async function remove(key) {
    try {
      await request(keyUrl(key), { method: 'DELETE' })
      if (selected?.key === key) setSelected(null)
      setError(null)
    } catch (err) {
      setError(err.message)
    }
    reload()
  }

  return (
    <div>
      {error && <p role="alert">Error: {error}</p>}
      <form onSubmit={handleSave}>
        <input placeholder="Key" value={newKey} onChange={e => setNewKey(e.target.value)} />
        <input placeholder="Value" value={newValue} onChange={e => setNewValue(e.target.value)} />
        <button type="submit">Save</button>
      </form>
      <ul>
        {keys.map(key => (
          <li key={key}>
            <button type="button" onClick={() => show(key)}>
              {key}
            </button>
            <button type="button" onClick={() => remove(key)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
      {selected && (
        <div>
          <h3>{selected.key}</h3>
          <pre>{selected.value}</pre>
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'

export default function Todo() {
  const [text, setText] = useState('')
  const [items, setItems] = useState([])

  function handleSubmit(e) {
    e.preventDefault()
    const value = text.trim()
    if (!value) return
    setItems(prev => [...prev, { id: crypto.randomUUID(), text: value }])
    setText('')
  }

  function remove(id) {
    setItems(prev => prev.filter(item => item.id !== id))
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={text} onChange={e => setText(e.target.value)} />
        <button type="submit">Add</button>
      </form>
      <ul>
        {items.map(item => (
          <li key={item.id}>
            {item.text}
            <button type="button" onClick={() => remove(item.id)}>
              Remove
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}
